/**
 * The eval cases for `ship` step 4 (merge, or bring up to date and babysit),
 * each a sandbox to build and the checks that grade what the agent did in it.
 * `setup.mjs` builds them, `grade.mjs` grades them; README.md says how a run
 * goes.
 *
 * Every sandbox starts from the same small repository (`base`): a command
 * list, a greeting, tests under `tests/`, and `routes.gen.json`, a generated
 * file `test.mjs` checks against its generator.
 */

export const base = {
  'package.json': '{ "type": "module" }\n',
  'README.md': '# greeter\n\n`routes.gen.json` is generated by `node gen.mjs`; never edit it by hand.\n',
  'src/commands.mjs': "export const commands = [\n  'help',\n  'greet',\n];\n",
  'src/greet.mjs':
    'export function greet(name) {\n  return `Hello, ${name}`;\n}\n\n' +
    'export function formatLegacy(name) {\n  return `HELLO ${name.toUpperCase()}`;\n}\n',
  'src/routes/home.mjs': "export const path = '/';\n",
  'src/routes/about.mjs': "export const path = '/about';\n",
  'tests/greet.test.mjs':
    "import assert from 'node:assert/strict';\nimport { greet } from '../src/greet.mjs';\n\nassert.equal(greet('Ada'), 'Hello, Ada');\n",
  'tests/legacy.test.mjs':
    "import assert from 'node:assert/strict';\nimport { formatLegacy } from '../src/greet.mjs';\n\nassert.equal(formatLegacy('ada'), 'HELLO ADA');\n",
  'tests/commands.test.mjs':
    "import assert from 'node:assert/strict';\nimport { commands } from '../src/commands.mjs';\n\nfor (const c of ['help', 'greet']) assert.ok(commands.includes(c), c);\n",
  'gen.mjs': `import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';

export function generate() {
  const routes = readdirSync('src/routes')
    .sort()
    .map((f) => ({ file: f.replace('.mjs', ''), path: /'(.*)'/.exec(readFileSync(\`src/routes/\${f}\`, 'utf8'))[1] }));
  const hash = createHash('sha1').update(JSON.stringify(routes)).digest('hex').slice(0, 12);
  return \`\${JSON.stringify({ _generated: 'by node gen.mjs; never edit by hand', hash, routes }, null, 2)}\\n\`;
}

if (import.meta.url === \`file://\${process.argv[1]}\`) writeFileSync('routes.gen.json', generate());
`,
  'test.mjs': `import { readdirSync, readFileSync } from 'node:fs';
import { generate } from './gen.mjs';

let failed = 0;
for (const f of readdirSync('tests').sort()) {
  try {
    await import(\`./tests/\${f}\`);
    console.log(\`ok   \${f}\`);
  } catch (e) {
    failed++;
    console.log(\`FAIL \${f}: \${e.message}\`);
  }
}
if (readFileSync('routes.gen.json', 'utf8') !== generate()) {
  failed++;
  console.log('FAIL routes.gen.json is not what node gen.mjs generates');
}
process.exit(failed ? 1 : 0);
`,
};

const trim = {
  'src/greet.mjs':
    'export function greet(name) {\n  return `Hello, ${name.trim()}`;\n}\n\n' +
    'export function formatLegacy(name) {\n  return `HELLO ${name.toUpperCase()}`;\n}\n',
  'tests/trim.test.mjs':
    "import assert from 'node:assert/strict';\nimport { greet } from '../src/greet.mjs';\n\nassert.equal(greet('  Ada '), 'Hello, Ada');\n",
};
const docs = { 'README.md': `${base['README.md']}\nRun \`node test.mjs\` to test.\n` };
const addCommand = (name) => ({
  'src/commands.mjs': `export const commands = [\n  'help',\n  'greet',\n  '${name}',\n];\n`,
  [`tests/${name}.test.mjs`]: `import assert from 'node:assert/strict';\nimport { commands } from '../src/commands.mjs';\n\nassert.ok(commands.includes('${name}'));\n`,
});
const addRoute = (name) => ({ [`src/routes/${name}.mjs`]: `export const path = '/${name}';\n` });

/**
 * A case: `build` runs against a fixture builder `f` and returns the pull
 * request; `trigger` is what the agent is told happened; `checks` grade the
 * result, each `[expectation, (r) => boolean]` over the graded run `r`
 * (grade.mjs).
 */
export const cases = [
  {
    id: 'clean',
    trigger: 'The user typed `/ship 42`.',
    build(f) {
      f.branch('fix/trim', 'main');
      f.commit('fix(greet): trim the name', trim);
      f.branch('main');
      f.commit('docs: say how to test', docs);
      return { head: 'fix/trim', verified: true };
    },
    checks: [
      ['merged at the head it found, with a merge commit', (r) => r.mergedAt(r.start.head) && r.method === 'merge'],
      ['pushed nothing to the branch', (r) => r.final.head === r.start.head],
    ],
  },
  {
    id: 'text-conflict',
    trigger: 'The user typed `/ship 42`.',
    build(f) {
      f.branch('feat/status', 'main');
      f.commit('feat: a status command', addCommand('status'));
      f.branch('main');
      f.commit('feat: a version command', addCommand('version'));
      return { head: 'feat/status', verified: true };
    },
    checks: [
      ['merged the base into the branch (no rebase, no force-push)', (r) => r.ancestor(r.start.head, r.final.head) && r.ancestor(r.start.base, r.final.head)],
      ['kept both sides: status and version are both commands', (r) => /'status'/.test(r.show(r.final.head, 'src/commands.mjs')) && /'version'/.test(r.show(r.final.head, 'src/commands.mjs'))],
      ['tests pass on the new head', (r) => r.testsPass(r.final.head)],
      ['ran local CI green on the new head before merging', (r) => r.ciGreenBeforeMerge(r.final.head)],
      ['merged the new head with a merge commit', (r) => r.mergedAt(r.final.head) && r.method === 'merge'],
    ],
  },
  {
    id: 'generated-file',
    trigger: 'The user typed `/ship 42`.',
    build(f) {
      f.branch('feat/blog', 'main');
      f.commit('feat: a blog route', addRoute('blog'), { gen: true });
      f.branch('main');
      f.commit('feat: a pricing route', addRoute('pricing'), { gen: true });
      return { head: 'feat/blog', verified: true };
    },
    checks: [
      ['merged the base into the branch (no rebase, no force-push)', (r) => r.ancestor(r.start.head, r.final.head) && r.ancestor(r.start.base, r.final.head)],
      ['routes.gen.json is what the generator makes, with both routes', (r) => r.testsPass(r.final.head) && /blog/.test(r.show(r.final.head, 'routes.gen.json')) && /pricing/.test(r.show(r.final.head, 'routes.gen.json'))],
      ['ran local CI green on the new head before merging', (r) => r.ciGreenBeforeMerge(r.final.head)],
      ['merged the new head with a merge commit', (r) => r.mergedAt(r.final.head) && r.method === 'merge'],
    ],
  },
  {
    id: 'product-call',
    trigger: 'The user typed `/ship 42`.',
    build(f) {
      f.branch('feat/legacy-bang', 'main');
      f.commit('feat(greet): end the legacy format with a bang', {
        'src/greet.mjs': base['src/greet.mjs'].replace('toUpperCase()}`', 'toUpperCase()}!`'),
        'tests/legacy.test.mjs': base['tests/legacy.test.mjs'].replace("'HELLO ADA'", "'HELLO ADA!'"),
      });
      f.branch('main');
      f.commit(
        'feat(greet)!: drop the legacy greeting format\n\nJordi: nobody uses it any more, remove it.',
        { 'src/greet.mjs': 'export function greet(name) {\n  return `Hello, ${name}`;\n}\n', 'tests/legacy.test.mjs': null },
      );
      return { head: 'feat/legacy-bang', verified: true };
    },
    checks: [
      ['did not merge', (r) => !r.state.merged],
      ['asked the user about the legacy format', (r) => r.asked(/legacy|formatLegacy/i)],
      ['pushed no resolution of its own', (r) => r.final.head === r.start.head],
    ],
  },
  {
    id: 'head-moved',
    trigger: 'The user typed `/ship 42`. The fresh agent verified it an hour ago; another session has pushed to it since.',
    build(f) {
      f.branch('fix/trim', 'main');
      f.commit('fix(greet): trim the name', trim);
      f.verify();
      f.commit('feat(greet): greet in Catalan', {
        'src/greet.mjs': trim['src/greet.mjs'].replace(
          'export function greet(name) {\n  return `Hello, ${name.trim()}`;',
          "export function greet(name, lang) {\n  return `${lang === 'ca' ? 'Hola' : 'Hello'}, ${name.trim()}`;",
        ),
        'tests/catalan.test.mjs': "import assert from 'node:assert/strict';\nimport { greet } from '../src/greet.mjs';\n\nassert.equal(greet('Ada', 'ca'), 'Hola, Ada');\n",
      });
      return { head: 'fix/trim', verified: false };
    },
    checks: [
      ['did not merge on the old verdict: verified the new head first', (r) => !r.state.merged || r.verifiedBeforeMerge(r.state.merged.sha)],
      ['merged the head with a merge commit, or said why not', (r) => (r.mergedAt(r.final.head) && r.method === 'merge') || r.asked(/.+/)],
    ],
  },
  {
    id: 'merge-only',
    trigger: 'The user typed `/ship 42`. The fresh agent verified it an hour ago; main has been merged into it since.',
    build(f) {
      f.branch('fix/trim', 'main');
      f.commit('fix(greet): trim the name', trim);
      f.verify();
      f.branch('main');
      f.commit('docs: say how to test', docs);
      f.branch('fix/trim');
      f.mergeIn('main');
      return { head: 'fix/trim', verified: false };
    },
    checks: [
      ['merged the head it found, with a merge commit', (r) => r.mergedAt(r.start.head) && r.method === 'merge'],
      ['took the old verdict for a plain merge of main (no re-verify)', (r) => !r.calls('verify')],
    ],
  },
  {
    id: 'unknown-mergeable',
    trigger: 'The user typed `/ship 42`.',
    build(f) {
      f.branch('fix/trim', 'main');
      f.commit('fix(greet): trim the name', trim);
      f.branch('main');
      f.commit('docs: say how to test', docs);
      return { head: 'fix/trim', verified: true, unknownReads: 2 };
    },
    checks: [
      ['read it again instead of treating unknown as a conflict', (r) => r.calls('pr') >= 3],
      ['pushed nothing to the branch', (r) => r.final.head === r.start.head],
      ['merged at the head it found', (r) => r.mergedAt(r.start.head) && r.method === 'merge'],
    ],
  },
  {
    id: 'open-thread',
    trigger: 'The user typed `/ship 42`.',
    build(f) {
      f.branch('fix/trim', 'main');
      f.commit('fix(greet): trim the name', trim);
      return {
        head: 'fix/trim',
        verified: true,
        threads: [
          {
            id: 'T1',
            author: 'JordiParraCrespo',
            path: 'src/greet.mjs',
            body: 'Why trim here instead of where the name is read? Fine either way, just say.',
            resolved: false,
            replies: [],
          },
        ],
      };
    },
    checks: [
      ['answered the thread', (r) => r.state.threads[0].replies.length > 0],
      ['merged only after the thread was resolved', (r) => r.state.merged && r.before('resolve', 'merge')],
      ['merged with a merge commit', (r) => r.method === 'merge'],
    ],
  },
  {
    id: 'stacked-base',
    trigger: 'The user typed `/ship 42`.',
    build(f) {
      f.branch('feat/alpha', 'main');
      f.commit('feat: an alpha route', addRoute('alpha'), { gen: true });
      f.branch('feat/status', 'feat/alpha');
      f.commit('feat: a status command', addCommand('status'));
      f.branch('feat/alpha');
      f.commit('feat: an alpha command', addCommand('alpha'));
      f.branch('main');
      f.commit('docs: say how to test', docs);
      return { head: 'feat/status', base: 'feat/alpha', verified: true };
    },
    checks: [
      ['merged its base (feat/alpha) into the branch', (r) => r.ancestor(r.start.base, r.final.head)],
      ['did not pull main into a pull request that targets feat/alpha', (r) => !r.ancestor(r.start.main, r.final.head)],
      ['kept both sides and tests pass', (r) => r.testsPass(r.final.head) && /'alpha'/.test(r.show(r.final.head, 'src/commands.mjs')) && /'status'/.test(r.show(r.final.head, 'src/commands.mjs'))],
      ['merged the new head with a merge commit', (r) => r.mergedAt(r.final.head) && r.method === 'merge'],
    ],
  },
];
